  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is an integer between -10^9 and 10^9.';
  if (!Number.isInteger(indexDiff) || indexDiff < 1 || indexDiff > nums.length) return 'indexDiff is between 1 and nums.length.';
  if (!Number.isInteger(valueDiff) || valueDiff < 0 || valueDiff > 1000000000) return 'valueDiff is between 0 and 10^9.';
  return null;
}

