function containsNearbyAlmostDuplicate(nums, indexDiff, valueDiff) {
  const sorted = [];

  function lowerBound(target) {
    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  }

  for (let i = 0; i < nums.length; i++) {
    const pos = lowerBound(nums[i] - valueDiff);
    if (pos < sorted.length && sorted[pos] <= nums[i] + valueDiff) {
      return true;
    }
    sorted.splice(lowerBound(nums[i]), 0, nums[i]);
    if (i >= indexDiff) {
      sorted.splice(lowerBound(nums[i - indexDiff]), 1);
    }
  }
  return false;
}

