function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const nums = Array.from({ length: n }, () => pick(-1000000000, 1000000000));
    const indexDiff = pick(1, n);
    const valueDiff = rand() < 0.5 ? pick(0, 100) : pick(0, 10000000);
    return [nums, indexDiff, valueDiff];
  }
  const n = pick(2, 9);
  const wide = rand() < 0.3;
  const nums = Array.from({ length: n }, () => (wide ? pick(-1000000000, 1000000000) : pick(-6, 6)));
  const indexDiff = pick(1, n);
  const valueDiff = wide ? pick(0, 1000000000) : pick(0, 3);
  return [nums, indexDiff, valueDiff];
}
